import { data } from '@takaro/helpers';
import { ensureWaypointsModule } from './utils.js';

// The Waypoints Module declares these permissions, so they are matched against its id, not teleports'.
function holdsModulePermission(pog, code, moduleId) {
  return pog.roles.some(({ role }) =>
    role.permissions.some(
      ({ permission }) =>
        (permission.permission === 'ROOT' && !permission.module) ||
        (permission.permission === code && permission.module?.id === moduleId),
    ),
  );
}

async function main() {
  const { pog, gameServerId } = data;

  const { waypointsDefinition } = await ensureWaypointsModule();

  const allWaypoints = waypointsDefinition.latestVersion.commands;

  const waypointsWithPermission = allWaypoints
    .filter((waypoint) =>
      holdsModulePermission(
        pog,
        `WAYPOINTS_USE_${waypoint.trigger.toUpperCase()}_${gameServerId}`,
        waypointsDefinition.id,
      ),
    )
    .sort((a, b) => a.trigger.localeCompare(b.trigger));

  if (!waypointsWithPermission.length) {
    await pog.pm('There are no waypoints available.');
    return;
  }

  await pog.pm(`Available waypoints: ${waypointsWithPermission.map((waypoint) => waypoint.trigger).join(', ')}`);
}

await main();

import { takaro, data, TakaroUserError, checkPermission } from '@takaro/helpers';

function getWaypointName(name) {
  return `waypoint ${name}`;
}

async function main() {
  const { pog, gameServerId, trigger, module, itemId } = data;

  const triggeredCommand = module.version.commands.find((command) => command.id === itemId);

  if (!triggeredCommand) {
    throw new Error('Waypoint not found.');
  }

  if (!triggeredCommand.name.includes(`server ${gameServerId}`)) {
    console.log(`Waypoint ${trigger} is not for this server.`);
    return;
  }

  if (!checkPermission(pog, `WAYPOINTS_USE_${trigger.toUpperCase()}_${gameServerId}`)) {
    throw new TakaroUserError(`You are not allowed to use the waypoint ${trigger}.`);
  }

  const teleportsModule = (
    await takaro.module.moduleControllerSearch({
      filters: {
        name: ['teleports'],
      },
    })
  ).data.data[0];

  const variable = await takaro.variable.variableControllerSearch({
    filters: {
      key: [getWaypointName(trigger)],
      gameServerId: [gameServerId],
      moduleId: [teleportsModule.id],
    },
  });

  if (variable.data.data.length === 0) {
    throw new TakaroUserError(`Waypoint ${trigger} does not exist.`);
  }

  const waypoint = JSON.parse(variable.data.data[0].value);

  await takaro.gameserver.gameServerControllerTeleportPlayer(gameServerId, pog.playerId, {
    x: waypoint.x,
    y: waypoint.y,
    z: waypoint.z,
    dimension: waypoint.dimension,
  });

  await pog.pm(`Teleported to waypoint ${trigger}.`);
}

await main();

